/* TweenLite 兼容层（精简版）
   原 TweenLite.min.js 文件缺失，这里实现本项目实际用到的 API：
   TweenLite.to(target, duration, { css: {...}, onUpdate, onComplete })
   用于返回顶部滚动动画与子菜单高度动画。 */
var TweenLite = (function () {
  'use strict';

  function easeOut(t) {
    return 1 - Math.pow(1 - t, 2);
  }

  function resolveElement(target) {
    if (!target) return null;
    if (target.nodeType === 1) return target;
    if (target[0] && target[0].nodeType === 1) return target[0]; // jQuery 对象
    return null;
  }

  function to(target, duration, vars) {
    vars = vars || {};
    var delay = (vars.delay || 0) * 1000;
    duration = (duration || 0) * 1000;
    if (delay > 0) {
      setTimeout(function () { run(target, duration, vars); }, delay);
    } else {
      run(target, duration, vars);
    }
  }

  function run(target, duration, vars) {
    var element = resolveElement(target);
    var keys = [];
    var from = [];
    var toValues = [];
    var k;

    if (vars.css) {
      // 元素 CSS 属性动画（如 height）
      var style = element ? window.getComputedStyle(element) : null;
      for (k in vars.css) {
        if (!Object.prototype.hasOwnProperty.call(vars.css, k)) continue;
        keys.push(k);
        from.push(style ? (parseFloat(style[k]) || 0) : 0);
        toValues.push(parseFloat(vars.css[k]) || 0);
      }
    } else {
      // 普通对象数值属性动画（如 { pos: 0 }）
      for (k in target) {
        if (!Object.prototype.hasOwnProperty.call(target, k)) continue;
        if (typeof target[k] !== 'number' || typeof vars[k] !== 'number') continue;
        keys.push(k);
        from.push(target[k]);
        toValues.push(vars[k]);
      }
    }

    function apply(progress) {
      for (var i = 0; i < keys.length; i++) {
        var value = from[i] + (toValues[i] - from[i]) * progress;
        if (vars.css && element) {
          element.style[keys[i]] = value + 'px';
        } else {
          target[keys[i]] = value;
        }
      }
      if (typeof vars.onUpdate === 'function') vars.onUpdate();
    }

    if (duration <= 0) {
      apply(1);
      if (typeof vars.onComplete === 'function') vars.onComplete();
      return;
    }

    var startTime = performance.now();
    (function frame(now) {
      var progress = Math.min((now - startTime) / duration, 1);
      apply(easeOut(progress));
      if (progress < 1) {
        requestAnimationFrame(frame);
      } else if (typeof vars.onComplete === 'function') {
        vars.onComplete();
      }
    })(startTime);
  }

  return { to: to };
})();

// TweenMax 与缓动对象兼容（xenon 组件引用，实际缓动由 TweenLite 兼容层统一处理）
var TweenMax = TweenLite;

function tweenEase() {
  return {
    easeIn: function (t) { return t; },
    easeOut: function (t) { return t; },
    easeInOut: function (t) { return t; },
    none: function (t) { return t; }
  };
}

var Power1 = tweenEase(),
  Power2 = tweenEase(),
  Power3 = tweenEase(),
  Power4 = tweenEase(),
  Sine = tweenEase(),
  Circ = tweenEase(),
  Expo = tweenEase(),
  Quad = tweenEase(),
  Cubic = tweenEase(),
  Quart = tweenEase(),
  Quint = tweenEase(),
  Strong = tweenEase(),
  Back = tweenEase(),
  Bounce = tweenEase(),
  Elastic = tweenEase();
